"""Offline model-comparison report with user-owned portable annotations."""
from collections import Counter
import html
import json
from pathlib import Path
import re
import shutil
import statistics
import sys

from compare_cute_models import OUT, PREVIOUS, MODELS, TEXT_PROMPT, VISION_PROMPT, decision, post_decision

samples=json.loads((OUT/'samples.json').read_text(encoding='utf-8'))
total_images=sum(len(p['images'])for p in samples)
payload={'version':'cute-model-compare-v1','models':MODELS,'posts':[], 'sample_count':total_images,'post_count':len(samples), 'method':{'text_prompt':TEXT_PROMPT,'vision_prompt':VISION_PROMPT,'thinking':False,'temperature':0,'image_max_edge':1024, 'decision_layers':'图片结论仅判断可见匹配、图片主体及类型；帖子审核判断宠物、场所关联；outcome保留原综合结论，人工标注语义不变', 'citation_validation':'source-citations-v2: 原始主体保留；精确引用、可逆空格、唯一有序省略号片段；不确定引用不参与放行'}}
if (OUT/'selection-manifest.json').exists():payload['selection_manifest']=json.loads((OUT/'selection-manifest.json').read_text(encoding='utf-8'))
for p in samples:
    post={k:p[k] for k in ('note_id','content','keyword','note_url')}
    if p.get('jev_pass'):
        post['jev_pass'] = p['jev_pass']
    post['text_models']={}
    for model in MODELS:
        file=OUT/model/p['note_id']/'text.json'
        post['text_models'][model]=json.loads(file.read_text(encoding='utf-8')) if file.exists() else {'status':'pending'}
        if post['text_models'][model]['status']=='recognized':
            post['text_models'][model]['post_assessment']=post_decision(post['text_models'][model].get('validated',{'status':'不确定','targets':[]}))
    post['images']=[]
    for im in p['images']:
        relative='images/'+p['note_id']+'/'+im['name']
        dst=OUT/relative;dst.parent.mkdir(parents=True,exist_ok=True)
        if not dst.exists():shutil.copyfile(PREVIOUS/relative,dst)
        image={'name':im['name'],'id':p['note_id']+'/'+im['name'],'post_id':p['note_id'],'src':relative,'models':{}}
        for model in MODELS:
            file=OUT/model/p['note_id']/(im['name']+'.json')
            image['models'][model]=json.loads(file.read_text(encoding='utf-8')) if file.exists() else {'status':'pending'}
            record=image['models'][model]
            if record['status']=='recognized':
                text=post['text_models'][model].get('validated',{'status':'不确定','targets':[]})
                try:record.update(decision(text,record['parsed']))
                except (ValueError,KeyError,TypeError):record.update(status='error',error='invalid_match_structure')
        post['images'].append(image)
    payload['posts'].append(post)

encoded=json.dumps(payload,ensure_ascii=False).replace('</','<\/')
document='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>可爱描述主体 · 三模型对比与人工标注</title><style>
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#1e293b;background:#f4f6f8;color-scheme:light}*{box-sizing:border-box}body{margin:0}main{max-width:1660px;margin:auto;padding:30px 24px 70px}h1{font-size:30px;letter-spacing:-.6px;margin:8px 0 15px}h2{font-size:21px;margin:0 0 13px}h3{font-size:15px;margin:0 0 13px}p{line-height:1.8;margin:9px 0}small{font-size:12px;color:#687589}.intro{color:#66758a;max-width:1100px}.tagline{font-size:12px;letter-spacing:1.8px;color:#607b75}.notice{padding:15px 20px;border-left:3px solid #31705d;background:#e8f0ed;font-size:13px;line-height:1.85}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}.metric{background:white;border:1px solid #dbe3eb;border-radius:10px;padding:18px}.metric b{font-size:18px}.metric p{font-size:13px;color:#67748a}.toolbar{position:sticky;top:0;z-index:10;background:#f4f6f8f5;backdrop-filter:blur(10px);padding:12px 0;border-bottom:1px solid #d8e1e9;display:flex;flex-wrap:wrap;gap:9px;align-items:center}button,select,input,textarea{font:inherit}button,select{border:1px solid #ced9e3;border-radius:7px;padding:8px 12px;background:white;color:#2c4050}button{cursor:pointer}button[aria-pressed=true]{background:#1c5946;color:white}button:hover{border-color:#628978}textarea,input{border:1px solid #ced9e3;border-radius:6px;padding:9px;background:white;color:#20343e;width:100%}textarea{min-height:68px;resize:vertical}.save{margin-left:auto;font-size:12px;color:#587567}.post{margin-top:35px;border-top:1px solid #cfdce5;padding-top:25px;scroll-margin-top:80px}.post-head{display:flex;justify-content:space-between;gap:15px}.post a{font-size:13px;color:#237566;text-decoration:none}.body{white-space:pre-wrap;line-height:1.95;background:white;border:1px solid #dbe3eb;border-radius:10px;padding:22px;margin:13px 0 18px;font-size:15px;max-height:320px;overflow:auto}mark.kw{background:#ffe298;color:#ae3521;padding:1px 3px;border-radius:3px;font-weight:700}.models{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.model{background:white;border:1px solid #dbe3eb;border-radius:10px;padding:17px;min-width:0}.model .provider{font-size:11px;color:#708094;margin-bottom:10px}.badge{display:inline-block;font-size:12px;border-radius:5px;padding:4px 8px;white-space:nowrap}.ok{color:#206744;background:#e5f4e8}.no{color:#b13636;background:#fff0ed}.pending{color:#8c6b22;background:#fff6d9}.post-assessment{padding:8px 11px;margin:8px 0 14px;border:1px solid #dbe3eb;border-radius:8px;background:#f8fafc}.post-assessment p{margin:3px 0}.target{border-top:1px solid #e8edf1;padding:11px 0}.target b{font-size:16px}.target p{font-size:12px;color:#647586;margin:5px 0}.quote{border-left:2px solid #cbd6da;padding-left:10px;color:#405364!important}details{font-size:12px;line-height:1.8;margin-top:9px}summary{cursor:pointer;color:#618073}pre{white-space:pre-wrap;word-break:break-word;max-height:300px;overflow:auto;background:#f3f6f8;padding:10px;font-size:11px}.human{background:#edf3fb;border:1px solid #c7d9ed;border-radius:10px;padding:17px;margin:14px 0}.human-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}.human label{font-size:12px;display:block;color:#49627c}.human label>*{display:block;width:100%;margin-top:7px}.image-row{margin:19px 0 25px;display:grid;grid-template-columns:300px 1fr;gap:14px;border-top:1px solid #dce5ec;padding-top:20px}.photo{min-width:0}.photo a{display:block;position:relative}.photo img{display:block;width:100%;height:270px;object-fit:contain;background:#e8eef2;border:1px solid #dbe3eb;border-radius:10px}.photo .filename{display:block;margin:8px 0;font-size:13px}.photo .human{margin-top:10px;padding:13px}.photo select{width:100%;font-size:12px;margin:6px 0}.photo textarea{font-size:12px}.image-row .models{align-items:start}.image-row .model p{font-size:13px}.model-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:13px}.model-head b{font-size:14px}.outcome{font-size:13px;font-weight:650}.comparison{margin:10px 0;border-top:1px solid #e3eaf0;padding-top:10px;font-size:12px;color:#677b8c}.hidden,[hidden]{display:none!important}.empty{padding:15px;color:#708094}.reference{font-size:13px;color:#546980;margin:12px 0}.rank{font-size:12px;margin-top:7px;color:#546980}footer{font-size:12px;border-top:1px solid #dce5ec;padding-top:23px;color:#667e8e;line-height:1.9}.overall{margin-bottom:20px}.nav{display:flex;gap:14px;flex-wrap:wrap;margin:20px 0}.nav a{font-size:13px;color:#247264;text-decoration:none}@media(max-width:1150px){.image-row{grid-template-columns:230px 1fr}.models{gap:8px}.model{padding:12px}.model-head{display:block}.model-head .badge{margin-top:8px}}@media(max-width:850px){.image-row{grid-template-columns:1fr}.photo img{height:300px}.photo .human{max-width:100%}.human-grid{grid-template-columns:1fr}.metrics{grid-template-columns:1fr}.models{grid-template-columns:1fr}.toolbar{position:static}main{padding:20px 14px}}
</style></head><body><main><span class="tagline">SAME SAMPLES · THINKING OFF · HUMAN REVIEW</span><h1>“可爱”描述谁？三个模型的回答放在一起看</h1><p class="intro">6 条真实帖子 · 49 张图片。先各自抽取正文评价主体，再用各自抽出的主体寻找配图；三个模型使用相同提示词、温度 0 和最长边 1024 像素的图片。此页比较整条链路，文本抽取错误可能传递到图片匹配。</p><div class="notice">图片右上角只显示图片结论；宠物身份与场所关联放在上方“帖子审核”中。图片通过不代表帖子整体通过。已有人工最终结论继续按综合结论统计，标注保留。<br>正文里的 <mark class="kw">可爱</mark> 已高亮。模型标签来自本次实际输出与统一判断规则，没有沿用旧模型分类。宠物所有权不能因“图片有狗”而放宽；同类别同时涉及宠物和其他动物时待核对。<br>人工标注由你填写，不预填模型答案；保存到当前浏览器，并可导出／导入 JSON。不会写回正式审核。Spark 使用原有 Q4_K_M 权重，加独立 F16 视觉投影；与云端的精度和服务环境不同，耗时包含网络、排队及重试。</div><div class="metrics" id="metrics"></div><div class="toolbar"><button data-filter="all" aria-pressed="true">全部图片</button><button data-filter="disagree" aria-pressed="false">图片结论不同</button><button data-filter="pending" aria-pressed="false">图片／帖子待核对</button><button data-filter="unmarked" aria-pressed="false">人工未标注</button><button id="export">导出人工标注</button><button id="import">导入人工标注</button><input id="import-file" type="file" accept=".json,application/json" hidden><span class="save" id="save-state">人工标注未填写</span></div><div class="nav" id="nav"></div><div id="posts"></div><details><summary>完整试验规则与参数</summary><pre id="method"></pre></details><footer>本次为探索性规则对比，提示词包含领域示例，不作为独立盲测。这里没有预先确认的人工真值标签。页面的“人工一致”只统计你实际标注的图片结论，不能代表总体准确率。小样本、量化与不同服务环境都会影响比较。<br>关闭思考模式参数依据：<a href="https://docs.siliconflow.cn/docs/api/chat-completions-post">硅基流动接口文档</a>、<a href="https://huggingface.co/Qwen/Qwen3.8-27B/blob/main/README.md">Qwen 官方说明</a>。本地使用 llama-server --reasoning off；所有请求保留思考字段检测记录。</footer></main><script id="report-data" type="application/json">__DATA__</script><script>
const report=JSON.parse(document.getElementById('report-data').textContent),keys=Object.keys(report.models),STORE=report.selection_manifest?.annotation_storage_key||'cute-model-compare-v1-20261013';
const allowed={outcome:['','不排除','排除','待核对'],match:['','包含','不包含','不确定'],subject:['','人物','食物','二者都不是','不确定'],type:['','实景照片','宣传海报','广告设计图','聊天截图','网页截图','文字／图文设计卡片','不确定']};
let marks={posts:{},images:{}},filterMode='all';
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function highlight(v){return esc(v).replace(/可爱/g,'<mark class="kw">可爱</mark>')}
function tone(v){return ['不排除','包含','明确','引用已修复并核实','原文引用已核实'].includes(v)?'ok':['排除','不包含'].includes(v)?'no':'pending'}
function badge(v){return '<span class="badge '+tone(v)+'">'+esc(v||'待完成')+'</span>'}
function categoryName(t){if(['真实动物','动物造型实体'].includes(t.kind)){for(const x of ['熊猫','猫','狗','鹿'])if(t.name?.includes(x))return x;if(/犬|拉布拉多/.test(t.name||''))return '狗'}return t.name||'不确定'}
function sanitize(input){
 if(!input||typeof input!=='object')throw new Error('格式错误');const result={posts:{},images:{}};
 for(const p of report.posts){const x=input.posts?.[p.note_id];if(x&&typeof x==='object')result.posts[p.note_id]={target:typeof x.target==='string'?x.target.slice(0,500):'',outcome:allowed.outcome.includes(x.outcome)?x.outcome:'',note:typeof x.note==='string'?x.note.slice(0,2000):''};
 for(const im of p.images){const x=input.images?.[im.id];if(x&&typeof x==='object'){const v={note:typeof x.note==='string'?x.note.slice(0,2000):''};for(const k of Object.keys(allowed))v[k]=allowed[k].includes(x[k])?x[k]:'';result.images[im.id]=v}}}return result;
}
try{const stored=localStorage.getItem(STORE);if(stored)marks=sanitize(JSON.parse(stored));else for(const key of report.selection_manifest?.annotation_legacy_keys||[]){const old=localStorage.getItem(key);if(old){const migrated=sanitize(JSON.parse(old));marks={posts:{...migrated.posts,...marks.posts},images:{...migrated.images,...marks.images}}}}}catch(e){document.getElementById('save-state').textContent='浏览器保存不可用，请使用导出按钮'}
function select(scope,id,field,title){const v=marks[scope][id]?.[field]||'';return '<label>'+title+'<select data-scope="'+scope+'" data-id="'+esc(id)+'" data-field="'+field+'">'+allowed[field].map(x=>'<option value="'+esc(x)+'"'+(x===v?' selected':'')+'>'+esc(x||'未标注')+'</option>').join('')+'</select></label>'}
function input(scope,id,field,title,area=false){const v=marks[scope][id]?.[field]||'',attrs=' data-scope="'+scope+'" data-id="'+esc(id)+'" data-field="'+field+'" maxlength="'+(field==='target'?500:2000)+'"';return '<label>'+title+(area?'<textarea'+attrs+'>'+esc(v)+'</textarea>':'<input'+attrs+' value="'+esc(v)+'">')+'</label>'}
function raw(record){return '<details><summary>原始输出、校验及耗时</summary><pre>'+esc(JSON.stringify(record,null,2))+'</pre></details>'}
function jevPanel(p){const j=p.jev_pass;if(!j)return '';return '<div class="post-assessment"><p><span class="badge ok">Jev 已通过 · keep</span> 本批入选依据，非人工真值</p><details><summary>查看 Jev 评价证据、场所证据及来源</summary><p>评价证据：'+highlight(j.evidence)+'</p><p>场所证据：'+highlight(j.target_evidence)+'</p><p>置信度 '+esc(j.confidence)+' · 证据核验 '+esc(j.verification_confidence)+'</p><p>'+esc(j.workbook)+' · '+esc(j.sheet)+' 第 '+esc(j.row)+' 行<br>'+esc(j.checkpoint)+' 第 '+esc(j.checkpoint_line)+' 行</p></details></div>'}
function textPanel(model,record){const value=record.validated||{};let body='';if(record.status==='recognized'){body='<div class="post-assessment"><p>帖子审核：'+badge(record.post_assessment?.post_outcome||'待核对')+'</p><p>'+esc(record.post_assessment?.post_decision_reason||'帖子条件待核对')+'</p></div><p>模型主体判断：'+badge(value.semantic_status||value.status)+'</p><p>链路可用状态：'+badge(value.status)+'</p><p>'+esc(value.reason)+'</p>'+(value.targets||[]).map(t=>{const c=t.citation||{},label=c.status==='repaired'?'引用已修复并核实':c.status==='unverified'?'引用待核对，暂不用于图片放行':'原文引用已核实';return '<div class="target"><b>'+esc(categoryName(t))+'</b>'+((categoryName(t)!==t.name)?'<small>（模型原名称：'+esc(t.name)+'）</small>':'')+'<p>'+esc([t.kind,t.ownership,t.place_relation].join(' · '))+'</p><p>'+badge(label)+'</p><p class="quote">'+highlight(t.evidence)+'</p>'+(c.status==='repaired'?'<details><summary>查看引用修复依据（未重跑正文模型）</summary><p>模型原引用：'+highlight(c.original)+'</p><p>对应原文片段：'+(c.spans||[]).map(x=>highlight(x.text)+'（字符 '+x.start+'–'+x.end+'）').join('<br>')+'</p><p>仅核实引用出处，不代表人工确认模型的语义判断。</p></details>':'')+'</div>'}).join('');if(!value.targets?.length)body+='<p>模型没有提取出可见主体。</p>';if(value.validation_warnings?.length)body+='<p class="badge pending">部分原文引用或目标字段待核对</p>'}else body=badge(record.status==='pending'?'待完成':'失败')+'<p>'+esc(record.error)+'</p>';return '<div class="model"><h3>'+esc(report.models[model].name)+'</h3><div class="provider">'+esc(report.models[model].provider)+'</div>'+body+raw(record)+'</div>'}
function imagePanel(model,record,id,targets){const v=record.parsed||{};const outcome=record.status==='recognized'?(record.image_outcome||'待核对'):(record.status==='pending'?'待完成':'失败');return '<div class="model"><div class="model-head"><b>'+esc(report.models[model].name)+'</b>'+'<span>图片结论：'+badge(outcome)+'</span></div><p>'+esc(record.image_decision_reason||record.error)+'</p><p>类别匹配：'+badge(record.match||'不确定')+'</p><p>主体：<b>'+esc(v.label||'—')+'</b><br>类型：'+esc(v.image_type||'—')+'</p><p>'+esc(v.reason)+'</p>'+(v.target_matches||[]).map(t=>'<p><b>'+esc(categoryName(targets.find(x=>x.id===t.id)||{name:t.id}))+' · '+esc(t.status)+'</b><br>'+esc(t.visible_evidence)+'</p>').join('')+'<small>请求耗时 '+esc(record.seconds??'—')+' 秒</small><div class="comparison" data-score="'+esc(id)+'" data-model="'+model+'"></div>'+raw(record)+'</div>'}
function render(){document.getElementById('nav').innerHTML=report.posts.map((p,i)=>'<a href="#p'+i+'">样本 '+(i+1)+'</a>').join('');document.getElementById('posts').innerHTML=report.posts.map((p,i)=>'<section class="post" id="p'+i+'"><div class="post-head"><h2>样本 '+(i+1)+' · '+esc(p.keyword)+' · '+p.images.length+' 张</h2><a href="'+esc(p.note_url)+'" target="_blank" rel="noopener">打开原帖 ↗</a></div><h3>原始正文</h3><div class="body">'+highlight(p.content)+'</div><h3>第一步 · 三模型各自提取评价主体</h3><div class="models">'+keys.map(k=>textPanel(k,p.text_models[k])).join('')+'</div><div class="human overall"><h3>人工标注 · 本帖正文</h3><div class="human-grid">'+input('posts',p.note_id,'target','“可爱”实际描述的主体')+select('posts',p.note_id,'outcome','正文是否应放行')+input('posts',p.note_id,'note','说明（可写宠物／场所关系）',true)+'</div></div><h3>第二步 · 同一张图片，横向比较三个结果</h3>'+p.images.map(im=>'<article class="image-row" data-image="'+esc(im.id)+'"><div class="photo"><a href="'+esc(im.src)+'" target="_blank" rel="noopener"><img src="'+esc(im.src)+'" loading="lazy" alt="'+esc(im.id)+'"></a><b class="filename">'+esc(im.name)+'</b><div class="human"><h3>人工标注 · 图片</h3>'+select('images',im.id,'outcome','你的综合结论（含帖子条件）')+select('images',im.id,'match','是否包含你确认的评价主体')+select('images',im.id,'subject','图片主体')+select('images',im.id,'type','图片类型')+input('images',im.id,'note','依据／备注',true)+'</div></div><div class="models">'+keys.map(k=>imagePanel(k,im.models[k],im.id,p.text_models[k].validated?.targets||[])).join('')+'</div></article>').join('')+'<p class="empty" hidden>当前筛选下没有图片。</p></section>').join('');document.getElementById('method').textContent=JSON.stringify(report.method,null,2);refresh();}
function stats(){const images=report.posts.flatMap(p=>p.images);return keys.map(key=>{const records=images.map(im=>im.models[key]),ok=records.filter(r=>r.status==='recognized'),seconds=ok.map(r=>r.seconds).filter(x=>typeof x==='number').sort((a,b)=>a-b);const median=seconds.length?(seconds[Math.floor((seconds.length-1)/2)]+seconds[Math.floor(seconds.length/2)])/2:null;const labelled=images.filter(im=>['不排除','排除'].includes(marks.images[im.id]?.outcome)&&['不排除','排除'].includes(im.models[key].outcome)),same=labelled.filter(im=>marks.images[im.id].outcome===im.models[key].outcome).length;return {key,done:ok.length,image_passed:ok.filter(r=>r.image_outcome==='不排除').length,post_pending:report.posts.filter(p=>p.text_models[key].post_assessment?.post_outcome==='待核对').length,failed:records.filter(r=>r.status==='error').length,median,labelled:labelled.length,same,thinking:records.filter(r=>r.thinking_warning).length+report.posts.filter(p=>p.text_models[key].thinking_warning).length}})}
function visible(im){const records=keys.map(k=>im.models[k]),outcomes=records.map(r=>r.status==='recognized'?r.image_outcome:r.status);return filterMode==='all'||filterMode==='disagree'&&new Set(outcomes).size>1||filterMode==='pending'&&records.some(r=>r.status!=='recognized'||r.outcome==='待核对')||filterMode==='unmarked'&&!marks.images[im.id]?.outcome}
function refresh(){document.getElementById('metrics').innerHTML=stats().map(s=>'<div class="metric"><b>'+esc(report.models[s.key].name)+'</b><p>'+esc(report.models[s.key].provider)+'</p><p>已输出 '+s.done+' / 49 张 · 失败 '+s.failed+'<br>单图耗时中位数 '+(s.median===null?'—':s.median.toFixed(2))+' 秒<br>图片不排除 '+s.image_passed+' 张 · 帖子待核对 '+s.post_pending+' 帖<br>人工综合结论一致 '+s.same+' / '+s.labelled+' 张（仅明确双向结论）'+(s.thinking?'<br><span class="badge pending">'+s.thinking+' 次返回了思考字段，请核对</span>':'')+'</p></div>').join('');for(const p of report.posts){let count=0;for(const im of p.images){const card=document.querySelector('[data-image="'+im.id+'"]');const show=visible(im);card.hidden=!show;if(show)count++;for(const key of keys){const score=card.querySelector('[data-model="'+key+'"]'),human=marks.images[im.id]?.outcome,model=im.models[key].outcome;score.textContent='综合结论：'+(model||'待完成')+' · '+(!human?'人工综合结论未标注':!model?'模型没有有效综合结论':human===model?'与人工综合结论一致':'与人工综合结论不同')}}document.getElementById('p'+report.posts.indexOf(p)).querySelector('.empty').hidden=count>0}}
function save(){try{localStorage.setItem(STORE,JSON.stringify(marks));document.getElementById('save-state').textContent='人工标注已保存到当前浏览器'}catch(e){document.getElementById('save-state').textContent='浏览器保存失败，请导出 JSON 备份'}}
function update(scope,id,field,value){if(!['posts','images'].includes(scope))return;marks[scope][id]??={};marks[scope][id][field]=value;save();refresh()}
document.getElementById('posts').addEventListener('input',e=>{const el=e.target;if(el.dataset.field)update(el.dataset.scope,el.dataset.id,el.dataset.field,el.value)});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filterMode=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));refresh()}));
function exportPayload(){return {version:report.version,batch_id:report.selection_manifest?.batch_id,exported_at:new Date().toISOString(),annotations:marks}}
document.getElementById('export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(exportPayload(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='三模型对比-人工标注.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
document.getElementById('import').addEventListener('click',()=>document.getElementById('import-file').click());
document.getElementById('import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw new Error('文件过大');const v=JSON.parse(await file.text());if(v.version!==report.version)throw new Error('不是本批报告的人工标注');const imported=sanitize(v.annotations);marks={posts:{...marks.posts,...imported.posts},images:{...marks.images,...imported.images}};save();render()}catch(error){document.getElementById('save-state').textContent='导入失败：'+error.message}e.target.value=''});
render();if(Object.keys(marks.posts).length+Object.keys(marks.images).length)document.getElementById('save-state').textContent='已恢复当前浏览器的人工标注';
</script></body></html>'''.replace('__DATA__',encoded)
